import {currencies,statuses,amount,balance,totals,validate,emptyData,demoData} from './model.js';
const $=s=>document.querySelector(s);const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const id=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};const fmtDate=d=>new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'});const money=(v,c)=>new Intl.NumberFormat('en-IE',{style:'currency',currency:c}).format(v/100);const hours=m=>`${Number((m/60).toFixed(2))} h`;
let mode='demo',data,page='overview',currency='USD',statusFilter='all',projectFilter='all',query='',editing=null,storageError=false;
try{mode=localStorage.getItem('fl-mode')||'demo';if(!['demo','personal'].includes(mode))mode='demo'}catch{storageError=true}
function load(){try{const raw=localStorage.getItem('fl-'+mode);data=raw?validate(JSON.parse(raw)):(mode==='demo'?demoData():emptyData());}catch{data=mode==='demo'?demoData():emptyData();storageError=true;}currency=data.projects[0]?.currency||'EUR';}
function save(){try{localStorage.setItem('fl-'+mode,JSON.stringify(data));localStorage.setItem('fl-mode',mode);storageError=false;}catch{storageError=true;toast('Browser storage is unavailable. Export a backup before leaving.')}render();}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function project(pid){return data.projects.find(p=>p.id===pid)}
function projectCell(p){return `<div class="project-cell"><span class="project-logo">${esc(p.name.slice(0,1))}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.platform||'Independent project')}</small></div></div>`}
function badge(s){return `<span class="badge ${s}">${s[0].toUpperCase()+s.slice(1)}</span>`}
function metric(label,value,note,featured=false,icon='↗'){return `<section class="metric ${featured?'featured':''}"><div class="metric-label">${label}<span class="metric-icon">${icon}</span></div><div class="metric-value money">${value}</div><div class="metric-note">${note}</div></section>`}
function currencySelect(){return `<select aria-label="Display currency" id="currency">${currencies.map(c=>`<option ${c===currency?'selected':''}>${c}</option>`).join('')}</select>`}
function sessionRows(rows){return rows.map(s=>{const p=project(s.projectId);return `<tr><td>${projectCell(p)}</td><td>${esc(s.note||'Work session')}<br><small class="muted" style="margin:4px 0 0;display:block">${fmtDate(s.date)} · ${s.date.slice(0,4)}</small></td><td>${hours(s.minutes)}</td><td class="money">${money(amount(s),p.currency)}</td><td>${badge(s.status)}</td><td><div class="row-actions">${s.status==='submitted'?`<button class="row-action" data-approve="${s.id}">Approve</button>`:''}<button class="row-action" data-edit-session="${s.id}">Edit</button></div></td></tr>`}).join('')}
function sessionsTable(rows,title,overview=false){return `<section class="panel table-panel"><div class="panel-head"><h2>${title}</h2>${overview?'<button class="text-button" data-nav="sessions">All sessions ↗</button>':`<small>${rows.length} sessions</small>`}</div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Project</th><th>Work / date</th><th>Time</th><th>Earnings</th><th>Status</th><th>Actions</th></tr></thead><tbody>${sessionRows(rows)}</tbody></table></div>`:'<div class="empty"><strong>Your next hour starts here.</strong>Log a work session to track its progress through approval.</div>'}</section>`}
function overview(){const t=totals(data,currency),out=t.approved-t.paid;const sorted=[...data.sessions].sort((a,b)=>b.date.localeCompare(a.date));const selectedIds=new Set(data.projects.filter(p=>p.currency===currency).map(p=>p.id));const selected=sorted.filter(s=>selectedIds.has(s.projectId));const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const date=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return {day:d.toLocaleDateString('en-GB',{weekday:'short'}),min:selected.filter(s=>s.date===date).reduce((n,s)=>n+s.minutes,0)}});const max=Math.max(60,...days.map(d=>d.min));const flow=t.submitted+t.approved;return `<div class="cards">${metric('Approved & unpaid',money(out,currency),'Approved earnings minus payouts',true,'↙')}${metric('Awaiting approval',money(t.submitted,currency),'Submitted work, not yet approved',false,'◷')}${metric('Received',money(t.paid,currency),'Payouts recorded · all time',false,'✓')}${metric('Time invested',hours(t.minutes),'All statuses · selected currency',false,'◴')}</div><div class="two-col"><section class="panel"><div class="panel-head"><h2>Your working rhythm</h2><small>Last 7 days</small></div><p class="panel-sub">Hours logged across your ${currency} projects</p><div class="chart">${days.map(d=>`<div class="bar-col"><div class="bar-space"><span class="bar-value">${hours(d.min)}</span><div class="bar" style="height:${d.min/max*86}px"></div></div><span class="bar-day">${d.day}</span></div>`).join('')}</div><div class="chart-footer">${hours(days.reduce((n,d)=>n+d.min,0))} logged this week · steady progress adds up.</div></section><section class="panel"><div class="panel-head"><h2>From work to payout</h2><small>${currency}</small></div><p class="panel-sub">Where your earnings stand · all time</p><div class="pipeline">${[['Awaiting approval',t.submitted,'#d8b779'],['Approved & unpaid',out,'#8ba98a'],['Received',t.paid,'#2d5745']].map(([l,v,c])=>`<div class="pipeline-row"><div class="pipeline-label"><span>${l}</span><strong class="money">${money(v,currency)}</strong></div><div class="track"><div class="fill" style="width:${flow?v/flow*100:0}%;background:${c}"></div></div></div>`).join('')}<p class="pipeline-note">Rejected work is excluded from earnings.<br>Each currency is tracked separately. No conversions.</p></div></section></div>${sessionsTable(selected.slice(0,5),'Recent work',true)}`}
function projectsView(){return data.projects.length?`<div class="project-grid">${data.projects.map(p=>{const rows=data.sessions.filter(s=>s.projectId===p.id);return `<article class="project-card"><span class="project-logo">${esc(p.name[0])}</span><h2>${esc(p.name)}</h2><p>${esc(p.platform||'Independent project')}</p><div class="rate">${money(p.rateCents,p.currency)} <small>/ hour</small></div><div class="project-details"><div><span>Time logged</span><strong>${hours(rows.reduce((n,s)=>n+s.minutes,0))}</strong></div><div><span>Approved & unpaid</span><strong>${money(balance(data,p.id),p.currency)}</strong></div><div><span>Awaiting approval</span><strong>${money(rows.filter(s=>s.status==='submitted').reduce((n,s)=>n+amount(s),0),p.currency)}</strong></div></div><div class="project-card-bottom"><button class="text-button" data-edit-project="${p.id}">Edit project</button><button class="row-action" data-log-project="${p.id}">＋ Log work</button></div></article>`}).join('')}</div>`:'<section class="panel empty"><strong>Make room for your first project.</strong>Add its name, hourly rate and currency to get started.</section>'}
function payoutsView(){const rows=[...data.payouts].sort((a,b)=>b.date.localeCompare(a.date));return `<div class="notice">Record money received against a project’s approved earnings. Partial payments are welcome; the remaining balance stays outstanding. Amounts are gross, in the project’s original currency.</div><section class="panel table-panel"><div class="panel-head"><h2>Payment history</h2><small>${rows.length} payouts</small></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Project</th><th>Received</th><th>Amount</th><th>Reference / note</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td>${projectCell(project(p.projectId))}</td><td>${fmtDate(p.date)} ${p.date.slice(0,4)}</td><td class="money">${money(p.amountCents,project(p.projectId).currency)}</td><td>${esc(p.note||'—')}</td><td><button class="row-action danger" data-delete-payout="${p.id}">Delete</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><strong>Your payments will land here.</strong>Once work is approved, record your first payout.</div>'}</section>`}
function render(){const names={overview:['Your freelance overview','A clear picture of your time, earnings, and what’s still on its way.','＋ Log work'],sessions:['Every hour, accounted for','Log your work, follow approvals, and keep your earnings in view.','＋ Log work'],projects:['Your independent work','One home for every project, platform, and hourly rate.','＋ New project'],payouts:['Follow the money','Know what has arrived, and what you’re still waiting for.','＋ Record payout']};const [title,desc,action]=names[page];$('#page-title').textContent=title;$('#page-description').textContent=desc;$('#main-action').textContent=action;$('#crumb').textContent={overview:'Overview',sessions:'Work sessions',projects:'Projects',payouts:'Payouts'}[page];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#demo-banner').hidden=mode!=='demo';$('#demo-banner').style.display=mode==='demo'?'flex':'none';$('#toggle-demo').textContent=mode==='demo'?'My workspace':'Explore demo';$('#save-state').textContent=storageError?'● Not saved · export a backup':'● Saved locally';$('#toolbar').innerHTML=page==='overview'?`<span>ALL-TIME SNAPSHOT</span><div class="filters"><span style="font-size:11px;color:#83917e">View currency</span>${currencySelect()}</div>`:page==='sessions'?`<div class="filters"><select id="filter-project" aria-label="Filter project"><option value="all">All projects</option>${data.projects.map(p=>`<option value="${p.id}" ${p.id===projectFilter?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select id="filter-status" aria-label="Filter status"><option value="all">All statuses</option>${statuses.map(s=>`<option ${s===statusFilter?'selected':''} value="${s}">${s[0].toUpperCase()+s.slice(1)}</option>`).join('')}</select></div><input class="search" id="search" aria-label="Search work notes" placeholder="Search work notes…" value="${esc(query)}">`:`<span>${page==='projects'?'YOUR PROJECTS':'RECORDED PAYOUTS'}</span><span>All currencies · no conversion</span>`;$('#content').innerHTML=page==='overview'?overview():page==='projects'?projectsView():page==='payouts'?payoutsView():sessionsTable([...data.sessions].filter(s=>(projectFilter==='all'||s.projectId===projectFilter)&&(statusFilter==='all'||s.status===statusFilter)&&s.note.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)),'Work log');}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function projectOptions(selected,eligible=data.projects){return `<label class="field">Project<select name="projectId" required>${eligible.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)} · ${p.currency}</option>`).join('')}</select></label>`}
function openForm(type,recordId=null,preset=null){$('#form-error').textContent='';editing={type,id:recordId};let html='';if(type==='project'){const p=project(recordId)||{name:'',platform:'',rateCents:6000,currency:'EUR'};const locked=data.sessions.some(s=>s.projectId===recordId)||data.payouts.some(s=>s.projectId===recordId);$('#modal-title').textContent=recordId?'Edit project':'A new project';html=field('Project name','name',p.name,'text','required maxlength="80" placeholder="e.g. AI response evaluation"')+field('Platform or workspace','platform',p.platform,'text','maxlength="80" placeholder="e.g. My freelance platform"')+`<div class="form-row">${field('Hourly rate','rate',p.rateCents/100,'number','required min="0.01" max="1000000" step="0.01"')}<label class="field">Currency<select name="currency" ${locked?'disabled':''}>${currencies.map(c=>`<option ${c===p.currency?'selected':''}>${c}</option>`).join('')}</select></label></div><p class="help">Rate changes apply to new sessions. Existing sessions retain their recorded rate.${locked?' Currency is fixed once work has been logged.':''}</p>${recordId&&!locked?'<button class="text-button danger" type="button" id="delete-project">Delete project</button>':''}`;
}else if(type==='session'){if(!data.projects.length){toast('Add your first project, then log your work.');return openForm('project')}const s=data.sessions.find(s=>s.id===recordId)||{projectId:preset||data.projects[0].id,date:today(),minutes:60,status:'submitted',note:'',rateCents:null};$('#modal-title').textContent=recordId?'Edit work session':'Log a work session';html=projectOptions(s.projectId)+`<div class="form-row">${field('Date','date',s.date,'date','required')}${field('Time worked (hours)','hours',s.minutes/60,'number','required min="0.016666" max="24" step="any"')}</div>`+`<div class="form-row">${field('Hourly rate','rate',(s.rateCents??project(s.projectId).rateCents)/100,'number','required min="0.01" max="1000000" step="0.01"')}<label class="field">Approval status<select name="status">${statuses.map(t=>`<option value="${t}" ${t===s.status?'selected':''}>${t[0].toUpperCase()+t.slice(1)}</option>`).join('')}</select></label></div><label class="field">Work notes<textarea name="note" maxlength="500" placeholder="What did you work on?">${esc(s.note)}</textarea></label><p class="help">Time is stored to the nearest minute. Earnings are rounded per session. Paid earnings cannot be removed.</p>${recordId?'<button class="text-button danger" type="button" id="delete-session">Delete session</button>':''}`;
}else{const eligible=data.projects.filter(p=>balance(data,p.id)>0);if(!eligible.length){toast('Approve some work before recording a payout.');return}$('#modal-title').textContent='Record a payout';html=projectOptions(eligible[0].id,eligible)+`<p class="help" id="payout-balance"></p><div class="form-row">${field('Date received','date',today(),'date','required')}${field('Amount received','amount','','number','required min="0.01" step="0.01"')}</div>`+field('Reference or note','note','','text','maxlength="500" placeholder="e.g. Weekly payout"')+'<p class="help">Enter the gross amount settled in the project’s currency, before fees or conversion. Fee tracking is not included in this version.</p>'}
$('#form-fields').innerHTML=html;if(type==='payout')updatePayoutBalance();$('#modal').showModal();}
function updatePayoutBalance(){const pid=$('#entry-form [name=projectId]').value;const left=balance(data,pid);$('#payout-balance').textContent=`Available to settle: ${money(left,project(pid).currency)}`;$('#entry-form [name=amount]').max=left/100;}
$('#entry-form').addEventListener('change',e=>{if(e.target.name==='projectId'){if(editing.type==='payout')updatePayoutBalance();if(editing.type==='session')$('#entry-form [name=rate]').value=project(e.target.value).rateCents/100;}});
$('#entry-form').addEventListener('submit',e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const next=structuredClone(data);try{if(editing.type==='project'){const old=project(editing.id);const p={id:editing.id||id(),name:f.name.trim(),platform:f.platform.trim(),rateCents:Math.round(Number(f.rate)*100),currency:f.currency||old?.currency};if(old)next.projects[next.projects.findIndex(x=>x.id===old.id)]=p;else next.projects.push(p);}else if(editing.type==='session'){const s={id:editing.id||id(),projectId:f.projectId,date:f.date,minutes:Math.round(Number(f.hours)*60),rateCents:Math.round(Number(f.rate)*100),status:f.status,note:f.note.trim()};if(editing.id)next.sessions[next.sessions.findIndex(x=>x.id===editing.id)]=s;else next.sessions.push(s);}else next.payouts.push({id:id(),projectId:f.projectId,date:f.date,amountCents:Math.round(Number(f.amount)*100),note:f.note.trim()});validate(next);data=next;save();$('#modal').close();toast('Saved to your '+(mode==='demo'?'demo':'personal')+' workspace.');}catch(err){$('#form-error').textContent=err.message;}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.classList.contains('close'))$('#modal').close();if(b.dataset.page||b.dataset.nav){page=b.dataset.page||b.dataset.nav;render()}if(b.dataset.editProject)openForm('project',b.dataset.editProject);if(b.dataset.logProject)openForm('session',null,b.dataset.logProject);if(b.dataset.editSession)openForm('session',b.dataset.editSession);if(b.dataset.approve){data.sessions.find(s=>s.id===b.dataset.approve).status='approved';save();toast('Work approved. Ready to reconcile a payout.')}if(b.dataset.deletePayout&&confirm('Delete this payout? Its amount will return to the outstanding balance.')){data.payouts=data.payouts.filter(p=>p.id!==b.dataset.deletePayout);save();toast('Payout removed.')}if(b.id==='delete-project'&&confirm('Delete this unused project?')){data.projects=data.projects.filter(p=>p.id!==editing.id);save();$('#modal').close()}if(b.id==='delete-session'&&confirm('Delete this work session?')){const next=structuredClone(data);next.sessions=next.sessions.filter(s=>s.id!==editing.id);try{validate(next);data=next;save();$('#modal').close()}catch(err){$('#form-error').textContent=err.message}}});
$('#main-action').onclick=()=>openForm(page==='projects'?'project':page==='payouts'?'payout':'session');
$('#toolbar').addEventListener('change',e=>{if(e.target.id==='currency')currency=e.target.value;if(e.target.id==='filter-project')projectFilter=e.target.value;if(e.target.id==='filter-status')statusFilter=e.target.value;render()});
$('#toolbar').addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;query=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
function switchMode(){mode=mode==='demo'?'personal':'demo';projectFilter='all';statusFilter='all';query='';load();try{localStorage.setItem('fl-mode',mode)}catch{}render();toast(mode==='personal'?'Your workspace. Add a project to begin.':'Demo workspace. Your personal records are kept separate.')}
$('#mode-switch').onclick=switchMode;$('#toggle-demo').onclick=switchMode;
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`freelance-ledger-${mode}-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported. Keep it somewhere safe.')};
$('#restore').onclick=()=>$('#restore-file').click();$('#restore-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error('Backup is too large (maximum 10 MB).');const next=validate(JSON.parse(await file.text()));if(confirm(`Replace the ${mode} workspace with this backup? Export current records first if you want to keep them.`)){data=next;projectFilter='all';currency=data.projects[0]?.currency||'EUR';save();toast('Backup restored.')}}catch(err){toast('Could not restore: '+err.message)}e.target.value=''};
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();page='overview';render()});
load();render();
